challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "mongo is the source of the P-CSCF SIP error ratio spike, the call setup failures, and the subsequent drops in UPF GTP-U traffic rates (L10).",
      "primary_suspect_nf": "mongo",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check the running status of the mongo container.",
          "expected_if_hypothesis_holds": "The mongo container status is reported as exited, down, or unhealthy.",
          "falsifying_observation": "The mongo container is reported as running and healthy.",
          "conflates_with": []
        },
        {
          "tool": "check_process_listeners",
          "args_hint": "Check listening ports on the mongo container.",
          "expected_if_hypothesis_holds": "The tool returns no active listeners for the standard mongo database port (e.g., 27017) or fails to execute because the container is down.",
          "falsifying_observation": "The tool returns an active TCP listener on the expected database port.",
          "conflates_with": []
        },
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Fetch PCF or UDR metrics to look for datastore connection error counters.",
          "expected_if_hypothesis_holds": "PCF or UDR metrics show elevated datastore connection error counters or timeouts.",
          "falsifying_observation": "PCF and UDR datastore connection error metrics are at normal baseline levels or zero.",
          "conflates_with": []
        }
      ],
      "notes": "Directly testing the L10 exited state claim for mongo. PCF/UDR metrics probe is included to verify the upstream impact of a blinded datastore."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "pcf is the source of the P-CSCF SIP error ratio spike, the call setup failures, and the subsequent drops in UPF GTP-U traffic rates.",
      "primary_suspect_nf": "pcf",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check the running status of the pcf container.",
          "expected_if_hypothesis_holds": "The pcf container status is reported as down, exited, or unhealthy.",
          "falsifying_observation": "The pcf container is reported as running and healthy.",
          "conflates_with": []
        },
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Check PCF metrics for policy association request counts and error rates.",
          "expected_if_hypothesis_holds": "PCF metrics show incoming N5 requests from P-CSCF alongside a high rate of 5xx error responses or zero outbound responses.",
          "falsifying_observation": "PCF metrics show no 5xx errors and a 1:1 ratio of successful responses to incoming requests.",
          "conflates_with": []
        },
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Check pcscf metrics for outbound N5/Rx policy requests to PCF (activity-vs-drops discriminator).",
          "expected_if_hypothesis_holds": "pcscf metrics show N5/Rx requests are actively being sent to pcf, but are timing out or receiving error codes.",
          "falsifying_observation": "pcscf metrics show no outbound N5 requests are being sent, or all sent requests receive immediate successful responses.",
          "conflates_with": []
        }
      ],
      "notes": "Includes the required activity-vs-drops discriminator checking the upstream (pcscf) N5 outbound rates to verify requests are actually reaching the PCF."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "pcscf is the source of the P-CSCF SIP error ratio spike, the call setup failures, and the subsequent drops in UPF GTP-U traffic rates.",
      "primary_suspect_nf": "pcscf",
      "probes": [
        {
          "tool": "run_kamcmd",
          "args_hint": "run_kamcmd('pcscf', 'dlg.list') to show active dialogs.",
          "expected_if_hypothesis_holds": "The tool returns a drop in active dialogs or zero active calls, particularly when prior state had calls and INVITE rates are non-zero.",
          "falsifying_observation": "The tool returns a typical value of active dialogs (e.g., ~1 per active VoUE), meaning calls are successfully maintaining state here.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "measure_rtt('pcscf', icscf_ip) to test the transport layer between P-CSCF and I-CSCF.",
          "expected_if_hypothesis_holds": "The probe shows 0% loss and low latency.",
          "falsifying_observation": "The probe shows high packet loss or unreachability.",
          "conflates_with": [
            "the network path between pcscf and icscf could be healthy while icscf is dropping or ignoring requests",
            "the icscf container might be down or unresponsive despite network-level reachability"
          ]
        },
        {
          "tool": "get_diagnostic_metrics",
          "args_hint": "Check ims.icscf.rcv_requests_register_per_ue to compare with pcscf forwarding rate.",
          "expected_if_hypothesis_holds": "The metric reads zero or dropping, consistent with requests not arriving at the I-CSCF despite the healthy network path.",
          "falsifying_observation": "The metric shows normal receive rates matching the pcscf inbound rates, confirming requests are successfully crossing the interface.",
          "conflates_with": []
        }
      ],
      "notes": "Addresses the compositional RTT probe by explicitly listing conflates_with elements (the path and the destination I-CSCF node) and provides a partner probe (I-CSCF metrics) to disambiguate."
    }
  ]
}
